select col_type_is('bidlock', 'auction_events', 'id', 'bigint', 'TC-019 DB-02 auction_events.id');
select col_type_is('bidlock', 'auction_events', 'auction_id', 'uuid', 'TC-019 DB-02 auction_events.auction_id');
