select col_type_is('bidlock', 'auction_events', 'at', 'timestamp with time zone', 'TC-019 DB-02 auction_events.at');
create temporary table fixture as select bidlock_test.auction() as id, bidlock_test.bidder() as bidder;
select throws_ok($$update bidlock.auctions set status = 'live', payment_state = 'paid', closed_at = null, settled_at = null where id = (select id from fixture)$$, '23514', null, 'TC-020 DB-02 rejects live / paid');
select throws_ok($$update bidlock.auctions set status = 'closed', payment_state = null, closed_at = bidlock.bidlock_now(), settled_at = null where id = (select id from fixture)$$, '23514', null, 'TC-020 DB-02 rejects closed / null');
select throws_ok($$update bidlock.auctions set status = 'settled', payment_state = null, closed_at = bidlock.bidlock_now(), settled_at = bidlock.bidlock_now() where id = (select id from fixture)$$, '23514', null, 'TC-020 DB-02 rejects settled / null');
select throws_ok($$update bidlock.auctions set bid_count = 1 where id = (select id from fixture)$$, '23514', null, 'TC-021 DB-02 price leader count consistency');
select throws_ok($$update bidlock.auctions set current_price = 1000 where id = (select id from fixture)$$, '23514', null, 'TC-021 DB-02 price leader count consistency');
select throws_ok($$update bidlock.auctions set leader_bidder_id = (select bidder from fixture) where id = (select id from fixture)$$, '23514', null, 'TC-021 DB-02 price leader count consistency');
select throws_ok($$update bidlock.auctions set last_bid_id = gen_random_uuid() where id = (select id from fixture)$$, '23514', null, 'TC-021 DB-02 price leader count consistency');
update bidlock.auctions set kind = 'public' where id = (select id from fixture);
select bidlock_test.auction() as second_id \gset
select throws_ok(format('update bidlock.auctions set kind = %L where id = %L', 'public', :'second_id'), '23505', null, 'TC-022 DB-02 one open public auction');
set local role bidlock_app;
select throws_ok('insert into bidlock.auctions default values', '42501', null, 'TC-023 DB-02 app cannot insert');
select throws_ok($$select bidlock._event(null, 'auction_created', null, '{}', null)$$, '42501', null, 'TC-025 DB-02 app cannot call _event');
reset role;
create role bidlock_probe nologin;
select is((select count(*) from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'bidlock' and has_function_privilege('bidlock_probe', p.oid, 'execute')), 0::bigint, 'TC-026 DB-02 no PUBLIC function execute');
select * from finish();
rollback;
